const data = $input.first().json;
const jobs = data.jobs || [];

const relevant = [
  'data analyst', 'junior data', 'data engineer', 'data scientist',
  'business intelligence', 'bi analyst', 'sql', 'python',
  'junior developer', 'software developer', 'backend', 'etl',
  'analytics', 'application support', 'systems administrator',
  'technical support', 'software engineer', 'developer'
];

const exclude = [
  'spiritual', 'care coordinator', 'nurse', 'therapist', 'bcba',
  'behavior analyst', 'chaplain', 'pastor', 'counselor',
  'social worker', 'teacher', 'instructor', 'recruiter',
  'sales', 'marketing', 'hr ', 'human resources',
  'vp ', 'vice president', 'director', 'senior ', 'sr.', 'sr ',
  'principal', 'staff ', 'lead ', 'head of', 'manager',
  'chief ', 'executive'
];

function cleanText(text = '') {
  return String(text)
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

return jobs
  .filter(j => {
    const title = (j.title || '').toLowerCase();
    const text = `${title} ${(j.tags || []).join(' ').toLowerCase()}`;

    const hasRelevant = relevant.some(k => text.includes(k));
    const hasExclude = exclude.some(k => text.includes(k));

    const startsSenior =
      /^(senior|sr\.?|vp|vice president|director|principal|staff|lead)\b/.test(title);

    return hasRelevant && !hasExclude && !startsSenior;
  })
  .map(j => ({
    json: {
      title: j.title || '',
      company: j.company_name || '',
      job_url: j.url || j.apply_url || j.link || '',
      description: cleanText(j.description).slice(0, 3500),
      location: j.candidate_required_location || 'Remote',
      source: 'Remotive',
      posted_date: j.publication_date || '',
      salary: j.salary || null,
      tags: Array.isArray(j.tags) ? j.tags.slice(0, 10) : []
    }
  }));

