for (let i = 0; i < items.length; i++) {
  const item = items[i];

  let parsed = null;

  // Gemini may already return parsed JSON
  if (item.json.jobs && Array.isArray(item.json.jobs)) {
    parsed = item.json;
  }

  // Gemini standard response structure
  if (!parsed && item.json.content?.parts?.[0]?.text) {
    const raw = item.json.content.parts[0].text
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      console.log(`Batch ${i}: JSON parse failed: ${e.message}`);
      continue;
    }
  }

  // Other simplified Gemini output possibilities
  if (!parsed && typeof item.json.text === 'string') {
    const raw = item.json.text
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      console.log(`Batch ${i}: JSON parse failed: ${e.message}`);
      continue;
    }
  }

  // Some n8n AI nodes put the result in output
  if (!parsed && typeof item.json.output === 'string') {
    const raw = item.json.output
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      console.log(`Batch ${i}: JSON parse failed: ${e.message}`);
      continue;
    }
  }

  if (!parsed) {
    console.log(`Batch ${i}: No usable Gemini response`);
    continue;
  }

  // Support either { jobs: [...] } or a direct array
  const jobs = Array.isArray(parsed)
    ? parsed
    : Array.isArray(parsed.jobs)
      ? parsed.jobs
      : [];

  if (jobs.length === 0) {
    console.log(`Batch ${i}: No scored jobs found`);
    continue;
  }

  for (const job of jobs) {
    const technicalFit = Math.min(
      35,
      Math.max(0, Number(job.technical_fit) || 0)
    );

    const roleFit = Math.min(
      20,
      Math.max(0, Number(job.role_fit) || 0)
    );

    const experienceFit = Math.min(
      20,
      Math.max(0, Number(job.experience_fit) || 0)
    );

    const locationFit = Math.min(
      15,
      Math.max(0, Number(job.location_fit) || 0)
    );

    const backgroundFit = Math.min(
      10,
      Math.max(0, Number(job.background_fit) || 0)
    );

    const matchScore =
      technicalFit +
      roleFit +
      experienceFit +
      locationFit +
      backgroundFit;

    let recommendation = 'skip';

    if (matchScore >= 75) {
      recommendation = 'apply';
    } else if (matchScore >= 60) {
      recommendation = 'consider';
    }

    results.push({
      json: {
        title: job.title || '',
        company: job.company || '',
        location: job.location || '',
        job_url: job.job_url || '',
        source: job.source || '',
        salary: job.salary ?? null,

        match_score: matchScore,

        technical_fit: technicalFit,
        role_fit: roleFit,
        experience_fit: experienceFit,
        location_fit: locationFit,
        background_fit: backgroundFit,

        strengths: Array.isArray(job.strengths)
          ? job.strengths
          : [],

        gaps: Array.isArray(job.gaps)
          ? job.gaps
          : [],

        recommendation
      }
    });
  }
}

return results;

