  const desc = String(j.description || '').toLowerCase();
  const location = String(j.location || '').toLowerCase();

  const text = `${title} ${desc} ${salary} ${location}`;

  // --------------------------------------------------
  // 1. DROP CLEAR SENIOR / LEADERSHIP TITLES
  // --------------------------------------------------

  const seniorTitle =
    /^(senior|sr\.?|staff|principal|lead|director|vp|vice president|head of|manager|chief)\b/i;

  if (seniorTitle.test(title)) {
    return false;
  }

  // --------------------------------------------------
  // 2. LOCATION / WORK ARRANGEMENT
  // --------------------------------------------------

  const isHybrid =
    /\bhybrid\b/i.test(text);

  const isRemote =
    /\bremote\b/i.test(text) ||
    /\bwork from home\b/i.test(text) ||
    /\bwork-from-home\b/i.test(text);

  const canWorkFromChina =
    /\bworldwide\b/i.test(text) ||
    /\bwork from anywhere\b/i.test(text) ||
    /\bremote worldwide\b/i.test(text) ||
    /\bworldwide remote\b/i.test(text) ||
    /\banywhere in the world\b/i.test(text) ||
    /\binternational remote\b/i.test(text) ||
    /\bglobal remote\b/i.test(text) ||
    /\bglobally remote\b/i.test(text) ||
    /\bopen globally\b/i.test(text);

  const isCanada =
    /\bcanada\b/i.test(location) ||
    /\bontario\b/i.test(location) ||
    /\btoronto\b/i.test(location) ||
    /\bottawa\b/i.test(location) ||
    /\bbritish columbia\b/i.test(location) ||
    /\bvancouver\b/i.test(location) ||
    /\bvictoria\b/i.test(location) ||
    /\balberta\b/i.test(location) ||
    /\bcalgary\b/i.test(location) ||
    /\bedmonton\b/i.test(location) ||
    /\bquebec\b/i.test(location) ||
    /\bmontreal\b/i.test(location) ||
    /\bmanitoba\b/i.test(location) ||
    /\bwinnipeg\b/i.test(location) ||
    /\bsaskatchewan\b/i.test(location) ||
    /\bsaskatoon\b/i.test(location) ||
    /\bregina\b/i.test(location) ||
    /\bnova scotia\b/i.test(location) ||
    /\bhalifax\b/i.test(location) ||
    /\bnew brunswick\b/i.test(location) ||
    /\bnewfoundland\b/i.test(location) ||
    /\bprince edward island\b/i.test(location);

  const requiresCanada =
    isCanada && !canWorkFromChina;

  // --------------------------------------------------
  // 3. PARSE SALARY
  // --------------------------------------------------

  let annualSalary = null;

  if (salary && salary !== 'null') {
    let cleanedSalary = salary;

    // Fix malformed values like $35,3k -> $35.3k
    cleanedSalary = cleanedSalary.replace(
      /(\d{1,3}),(\d)k\b/gi,
      '$1.$2k'
    );

    // Remove normal thousands separators
    cleanedSalary = cleanedSalary.replace(
      /(\d),(?=\d{3}\b)/g,
      '$1'
    );

    const numbers = [
      ...cleanedSalary.matchAll(
        /\$?\s*(\d+(?:\.\d+)?)\s*(k)?/gi
      )
    ]
      .map(match => {
        let value = parseFloat(match[1]);

        if (match[2]) {
          value *= 1000;
        }

        return value;
      })
      .filter(value =>
        Number.isFinite(value) &&
        value > 0
      );

    if (numbers.length > 0) {
      const lowSalary = Math.min(...numbers);

      if (
        /\bmonth\b/i.test(salary) ||
        /\bmonthly\b/i.test(salary) ||
        /\/mo\b/i.test(salary) ||
        /\bper month\b/i.test(salary)
      ) {
        annualSalary = lowSalary * 12;
      }

      else if (
        /\bhour\b/i.test(salary) ||
        /\bhourly\b/i.test(salary) ||
        /\/hr\b/i.test(salary) ||
        /\bper hour\b/i.test(salary)
      ) {
        annualSalary = lowSalary * 2080;
      }

      else if (
        /\bweek\b/i.test(salary) ||
        /\bweekly\b/i.test(salary) ||
        /\bper week\b/i.test(salary)
      ) {
        annualSalary = lowSalary * 52;
      }

      else {
        annualSalary = lowSalary;
      }
    }
  }

  // --------------------------------------------------
  // 4. SALARY RULES
  // --------------------------------------------------

  if (annualSalary !== null) {

    // Worldwide / China-compatible remote
    if (
      canWorkFromChina &&
      annualSalary < 36000
    ) {
      return false;
    }

    // Canada-based roles
    if (
      requiresCanada &&
      annualSalary < 70000
    ) {
      return false;
    }

    // Generic remote role with unclear international eligibility
    if (
      isRemote &&
      !requiresCanada &&
      !canWorkFromChina &&
      annualSalary < 36000
    ) {
      return false;
    }

    // Salary sanity ceiling
    if (annualSalary > 250000) {
      return false;
    }
  }

  return true;
});

